package com.wailsvlr.prism.modules;

import com.wailsvlr.prism.module.Category;
import com.wailsvlr.prism.module.Module;
import com.wailsvlr.prism.render.Highlight;
import com.wailsvlr.prism.render.HighlightStyle;
import com.wailsvlr.prism.setting.BoolSetting;
import com.wailsvlr.prism.setting.ColorSetting;
import com.wailsvlr.prism.setting.ModeSetting;
import com.wailsvlr.prism.setting.NumberSetting;
import com.wailsvlr.prism.setting.SectionSetting;
import net.minecraft.client.multiplayer.ClientLevel;
import net.minecraft.core.BlockPos;
import net.minecraft.resources.ResourceKey;
import net.minecraft.world.level.ChunkPos;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.chunk.LevelChunk;
import net.minecraft.world.level.chunk.LevelChunkSection;
import net.minecraft.world.level.material.FluidState;
import net.minecraft.world.phys.AABB;

import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Tells chunks that were just generated apart from chunks someone loaded before, and paints them, so the paths
 * players took show up as trails through fresh land.
 *
 * How: when a chunk is generated its water and lava only start flowing afterwards, so the client receives updates
 * of liquids starting to flow ("new"). A chunk someone loaded earlier arrives with its liquids already flowing
 * ("old"). Chunks without water or lava cannot be told apart.
 */
public class TrailFinder extends Module {
	private static final byte NEW = 1, OLD = 2;

	private final BoolSetting showNew, showOld, throughWalls, hudCount;
	private final ColorSetting newColor, oldColor;
	private final NumberSetting opacity, customY;
	private final ModeSetting height;

	/** Chunk age per dimension (kept while you stay on the server). */
	private final Map<ResourceKey<Level>, Map<Long, Byte>> ages = new HashMap<>();

	public TrailFinder() {
		super("TrailFinder", "Shows chunks players have been in before (old, green) apart from freshly generated ones (new, red): follow the green trails to bases", Category.RENDER);
		add(new SectionSetting("Chunks"));
		showOld = add(new BoolSetting("Old Chunks", "Chunks someone loaded before: trails, bases, highways", true));
		showNew = add(new BoolSetting("New Chunks", "Chunks generated just now: nobody has been here", true));
		add(new SectionSetting("Look"));
		oldColor = add(new ColorSetting("Old Color", "Colour of old chunks", 0xFF22C55E)).visibleWhen(showOld::isOn);
		newColor = add(new ColorSetting("New Color", "Colour of new chunks", 0xFFEF4444)).visibleWhen(showNew::isOn);
		opacity = add(new NumberSetting("Opacity", "Opacity of the chunk squares", 22, 5, 80, 1, "%"));
		height = add(new ModeSetting("Height", "Where the squares are drawn: under your feet, at sea level, or a height you choose", "Feet", "Feet", "Sea Level", "Custom"));
		customY = add(new NumberSetting("Custom Y", "Height of the squares", 64, -64, 320, 1, "")).visibleWhen(() -> height.is("Custom"));
		throughWalls = add(new BoolSetting("Through Walls", "Draw the squares over the terrain like a map", true));
		hudCount = add(new BoolSetting("HUD Counter", "Show old / new chunk counts in the HUD", true));
	}

	private Map<Long, Byte> current() {
		if (mc.level == null) return Map.of();
		return ages.computeIfAbsent(mc.level.dimension(), k -> new HashMap<>());
	}

	private static boolean flowing(FluidState f) { return !f.isEmpty() && !f.isSource(); }

	/** A chunk arrived: liquids that are already flowing mean someone loaded it before. */
	public void onChunkLoad(ClientLevel level, LevelChunk chunk) {
		if (!isEnabled()) return;
		Map<Long, Byte> map = ages.computeIfAbsent(level.dimension(), k -> new HashMap<>());
		long key = chunk.getPos().pack();
		if (map.containsKey(key)) return;   // the first verdict stays (our own visit makes liquids flow later)
		if (hasFlowingLiquid(chunk)) map.put(key, OLD);
	}

	private static boolean hasFlowingLiquid(LevelChunk chunk) {
		for (LevelChunkSection s : chunk.getSections()) {
			if (s == null || s.hasOnlyAir()) continue;
			if (!s.maybeHas(st -> flowing(st.getFluidState()))) continue;
			for (int y = 0; y < 16; y++) for (int z = 0; z < 16; z++) for (int x = 0; x < 16; x++)
				if (flowing(s.getBlockState(x, y, z).getFluidState())) return true;
		}
		return false;
	}

	/** A block changed (ClientLevelMixin): a liquid starting to flow in a chunk not seen as old means it was just made. */
	public void onBlockChanged(BlockPos pos, BlockState oldState, BlockState newState) {
		if (!isEnabled() || !flowing(newState.getFluidState()) || flowing(oldState.getFluidState())) return;
		Map<Long, Byte> map = current();
		map.putIfAbsent(ChunkPos.pack(pos.getX() >> 4, pos.getZ() >> 4), NEW);
	}

	/** Old and new chunks within {@code radius} chunks of you: [old, new]. */
	public int[] around(int radius) {
		int[] out = new int[2];
		if (mc.player == null) return out;
		int cx = mc.player.getBlockX() >> 4, cz = mc.player.getBlockZ() >> 4;
		for (Map.Entry<Long, Byte> e : current().entrySet()) {
			if (Math.abs(ChunkPos.getX(e.getKey()) - cx) > radius || Math.abs(ChunkPos.getZ(e.getKey()) - cz) > radius) continue;
			out[e.getValue() == OLD ? 0 : 1]++;
		}
		return out;
	}

	/** Compass direction from you towards the middle of the old chunks around you, or "" when there are none. */
	public String trailDirection(int radius) {
		if (mc.player == null) return "";
		int cx = mc.player.getBlockX() >> 4, cz = mc.player.getBlockZ() >> 4;
		double sx = 0, sz = 0;
		int n = 0;
		for (Map.Entry<Long, Byte> e : current().entrySet()) {
			if (e.getValue() != OLD) continue;
			int x = ChunkPos.getX(e.getKey()), z = ChunkPos.getZ(e.getKey());
			if (Math.abs(x - cx) > radius || Math.abs(z - cz) > radius) continue;
			sx += x * 16 + 8; sz += z * 16 + 8; n++;
		}
		if (n == 0) return "";
		BlockPos target = BlockPos.containing(sx / n, mc.player.getY(), sz / n);
		if (target.distSqr(mc.player.blockPosition()) < 24 * 24) return "around you";
		double dx = target.getX() + 0.5 - mc.player.getX(), dz = target.getZ() + 0.5 - mc.player.getZ();
		String[] names = {"S", "SW", "W", "NW", "N", "NE", "E", "SE"};
		double angle = Math.toDegrees(Math.atan2(-dx, dz));
		return names[(int) Math.round(((angle % 360) + 360) % 360 / 45) % 8];
	}

	public byte age(int chunkX, int chunkZ) { return current().getOrDefault(ChunkPos.pack(chunkX, chunkZ), (byte) 0); }

	public boolean showHudCount() { return hudCount.isOn(); }

	/** Forget everything (new server). */
	public void clear() { ages.clear(); }

	public void collect(List<Highlight> out) {
		if (!isEnabled() || mc.player == null || mc.level == null) return;
		double y = switch (height.get()) {
			case "Sea Level" -> mc.level.getSeaLevel();
			case "Custom" -> customY.get();
			default -> Math.floor(mc.player.getY()) - 0.98;
		};
		float a = opacity.getFloat() / 100f;
		HighlightStyle st = new HighlightStyle("Fill", 0, a, 1, throughWalls.isOn(), false, 0, false, 1e9, false, 1, 0, false);
		int cx = mc.player.getBlockX() >> 4, cz = mc.player.getBlockZ() >> 4;
		int r = mc.options.getEffectiveRenderDistance() + 1;
		for (Map.Entry<Long, Byte> e : current().entrySet()) {
			boolean old = e.getValue() == OLD;
			if (old ? !showOld.isOn() : !showNew.isOn()) continue;
			int x = ChunkPos.getX(e.getKey()), z = ChunkPos.getZ(e.getKey());
			if (Math.abs(x - cx) > r || Math.abs(z - cz) > r) continue;
			// a thin square a little inside the chunk border, so neighbours stay apart
			out.add(new Highlight(new AABB(x * 16 + 0.3, y, z * 16 + 0.3, x * 16 + 15.7, y + 0.04, z * 16 + 15.7),
				(old ? oldColor : newColor).rgb(), st, null));
		}
	}

	@Override
	public String getInfo() {
		int[] c = around(mc.options.getEffectiveRenderDistance());
		return c[0] + " old " + c[1] + " new";
	}
}
